WHERE strategy_case.is_deleted = 0
  AND (
      (
          strategy_case.case_status = 'GENERATING'
          AND strategy_case.created_at > #{visibleFrom}
      )
      OR (
          strategy_case.case_status = 'GENERATED'
          AND strategy_case.result_expires_at > #{visibleAt}
      )
      OR (
          strategy_case.case_status = 'GENERATION_FAILED'
          AND strategy_case.completed_at > #{visibleFrom}
      )
  )

  AND (

      strategy_case.strategy_case_id = #{query.strategyCaseId}
      OR

      UPPER(strategy_case.case_name) LIKE '%' || UPPER(#{query.searchText}) || '%' ESCAPE '\'
      OR UPPER(sku.sku_code) LIKE '%' || UPPER(#{query.searchText}) || '%' ESCAPE '\'
      OR UPPER(sku.sku_name) LIKE '%' || UPPER(#{query.searchText}) || '%' ESCAPE '\'
      OR UPPER(product.product_name) LIKE '%' || UPPER(#{query.searchText}) || '%' ESCAPE '\'
  )


  AND strategy_case.created_at >= #{query.createdFrom}


  AND strategy_case.created_at < #{query.createdToExclusive}


  AND EXISTS (
      SELECT 1
      FROM sales_point filter_sales_point
      JOIN sales_channel filter_sales_channel
        ON filter_sales_channel.sales_channel_id = filter_sales_point.sales_channel_id
      WHERE filter_sales_point.is_deleted = 0
        AND filter_sales_point.active_yn = 'Y'
        AND filter_sales_channel.is_deleted = 0
        AND filter_sales_channel.active_yn = 'Y'
        AND CASE
                WHEN filter_sales_point.sales_point_code = 'GREETING' THEN 'GREETING'
                WHEN filter_sales_point.sales_point_code = 'MODU_MATJIP' THEN 'ECOMMERCE'
                WHEN filter_sales_point.sales_point_code LIKE 'DEPT_%' THEN 'HYUNDAI_DEPT'
                WHEN filter_sales_point.sales_point_code LIKE 'HMART_%' THEN 'HMART'
                ELSE filter_sales_channel.channel_code
            END = #{query.channelType}
        AND (
            filter_sales_point.sales_point_id = strategy_case.requested_sales_point_id
            OR REGEXP_LIKE(
                strategy_case.request_payload_json,
                '.*"candidateSalesPointIds"\s*:\s*\[([^]]*,)?\s*'
                || TO_CHAR(filter_sales_point.sales_point_id, 'FM999999999999999999999999999999')
                || '\s*(,|\]).*'
            )
            OR (
                REGEXP_LIKE(
                    strategy_case.request_payload_json,
                    '.*"candidateSalesPointIds"\s*:\s*\[\s*\].*'
                )
                AND EXISTS (
                    SELECT 1
                    FROM inventory_balance channel_balance
                    WHERE channel_balance.sku_id = strategy_case.sku_id
                      AND channel_balance.is_deleted = 0
                      AND COALESCE(
                          channel_balance.stock_sales_point_id,
                          channel_balance.allocated_sales_point_id
                      ) = filter_sales_point.sales_point_id
                )
            )
        )
  )


  AND EXISTS (
      SELECT 1
      FROM inventory_balance warehouse_balance
      JOIN warehouse filter_warehouse
        ON filter_warehouse.warehouse_id = warehouse_balance.warehouse_id
      WHERE warehouse_balance.sku_id = strategy_case.sku_id
        AND warehouse_balance.is_deleted = 0
        AND filter_warehouse.is_deleted = 0
        AND filter_warehouse.active_yn = 'Y'
        AND filter_warehouse.warehouse_code = #{query.warehouseCode}
        AND (
            (
                warehouse_balance.lot_id IS NOT NULL
                AND REGEXP_LIKE(
                    strategy_case.request_payload_json,
                    '.*"lotIds"\s*:\s*\[([^]]*,)?\s*'
                    || TO_CHAR(warehouse_balance.lot_id, 'FM999999999999999999999999999999')
                    || '\s*(,|\]).*'
                )
            )
            OR (
                REGEXP_LIKE(
                    strategy_case.request_payload_json,
                    '.*"lotIds"\s*:\s*\[\s*\].*'
                )
                AND (
                    COALESCE(
                        warehouse_balance.stock_sales_point_id,
                        warehouse_balance.allocated_sales_point_id
                    ) = strategy_case.requested_sales_point_id
                    OR (
                        COALESCE(
                            warehouse_balance.stock_sales_point_id,
                            warehouse_balance.allocated_sales_point_id
                        ) IS NOT NULL
                        AND REGEXP_LIKE(
                            strategy_case.request_payload_json,
                            '.*"candidateSalesPointIds"\s*:\s*\[([^]]*,)?\s*'
                            || TO_CHAR(
                                COALESCE(
                                    warehouse_balance.stock_sales_point_id,
                                    warehouse_balance.allocated_sales_point_id
                                ),
                                'FM999999999999999999999999999999'
                            ) || '\s*(,|\]).*'
                        )
                    )
                    OR REGEXP_LIKE(
                        strategy_case.request_payload_json,
                        '.*"candidateSalesPointIds"\s*:\s*\[\s*\].*'
                    )
                )
            )
        )
  )


  AND TO_DATE(CAST(REGEXP_SUBSTR(
          strategy_case.request_payload_json,
          '"preferredStartDate"\s*:\s*"([0-9]{4}-[0-9]{2}-[0-9]{2})"',
          1, 1, NULL, 1
      ) AS VARCHAR2(10)), 'YYYY-MM-DD') <= #{query.strategyTo}
  AND TO_DATE(CAST(REGEXP_SUBSTR(
          strategy_case.request_payload_json,
          '"preferredEndDate"\s*:\s*"([0-9]{4}-[0-9]{2}-[0-9]{2})"',
          1, 1, NULL, 1
      ) AS VARCHAR2(10)), 'YYYY-MM-DD') >= #{query.strategyFrom}


  AND TO_DATE(CAST(REGEXP_SUBSTR(
          strategy_case.request_payload_json,
          '"preferredStartDate"\s*:\s*"([0-9]{4}-[0-9]{2}-[0-9]{2})"',
          1, 1, NULL, 1
      ) AS VARCHAR2(10)), 'YYYY-MM-DD') <= #{query.strategyFrom}
  AND TO_DATE(CAST(REGEXP_SUBSTR(
          strategy_case.request_payload_json,
          '"preferredEndDate"\s*:\s*"([0-9]{4}-[0-9]{2}-[0-9]{2})"',
          1, 1, NULL, 1
      ) AS VARCHAR2(10)), 'YYYY-MM-DD') >= #{query.strategyFrom}


  AND TO_DATE(CAST(REGEXP_SUBSTR(
          strategy_case.request_payload_json,
          '"preferredStartDate"\s*:\s*"([0-9]{4}-[0-9]{2}-[0-9]{2})"',
          1, 1, NULL, 1
      ) AS VARCHAR2(10)), 'YYYY-MM-DD') <= #{query.strategyTo}
  AND TO_DATE(CAST(REGEXP_SUBSTR(
          strategy_case.request_payload_json,
          '"preferredEndDate"\s*:\s*"([0-9]{4}-[0-9]{2}-[0-9]{2})"',
          1, 1, NULL, 1
      ) AS VARCHAR2(10)), 'YYYY-MM-DD') >= #{query.strategyTo}
